function formatarTelefoneBR(telefone) {
  if (!telefone) return "";

  let digits = String(telefone).replace(/\D/g, "");

  // Remove prefixo internacional 00
  if (digits.startsWith("00")) {
    digits = digits.substring(2);
  }

  // Se ainda não tiver 55, acrescenta Brasil
  if (!digits.startsWith("55")) {
    digits = "55" + digits;
  }

  return "+" + digits;
}

return contatos.map(contato => {

  const telefone = formatarTelefoneBR(contato.telefone);

  return {
    json: {
      first_name: contato.nome.trim(),
      last_name: contato.sobrenome.trim(),

      phone: telefone,
      whatsapp_phone: telefone,

      email: contato.email.trim(),

      gender: "xx",

      has_opt_in_sms: true,
      has_opt_in_email: true,

      consent_phrase: "aceito"
    }
  };
});
